<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  revisionHistoryLimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 保留多少个旧版本（用于回滚）</span></span>
